mapper.select:
select
	row_number() over() as num, a.*
from (
	select *			
	from board
	where 1=1
	
	and title like concat('%', #{searchText}, '%')
	
	
	order by 
		
			
				num ${orderType}
			
			
			
				num desc
			
		
	
	limit #{firstIndex}, #{recordCountPerPage}
) a

select writer
from board
where board_id = #{board_id}
